export function kClosestSorted(nums, k, target) {
    if (k < 0 || k > nums.length)
        return [];
    let l = 0, r = nums.length - k;
    while (l < r) {
        const m = Math.floor((l + r) / 2);
        if (target - nums[m] > nums[m + k] - target)
            l = m + 1;
        else
            r = m;
    }
    return nums.slice(l, l + k);
}
